import React from 'react';
import { FiMapPin } from 'react-icons/fi';

const ProductCard = ({ product, onClick }) => {
    const mainPhoto = product.photos && product.photos[0] ? `http://localhost:3001${product.photos[0]}` : null;

    const getCategoryIcon = (category) => {
        const icons = { telemovel: '📱', laptop: '💻', console: '🎮', tablet: '📟' };
        return icons[category] || '📦';
    };

    const getContactMethodIcon = (method) => {
        if (method === 'whatsapp') return '💚 WhatsApp';
        if (method === 'call') return '📞 Ligação';
        return '💚 WhatsApp / 📞 Ligação';
    };

    const getConditionText = (condition) => {
        switch(condition) {
            case 'novo': return 'Novo';
            case 'semi-novo': return 'Semi-novo';
            case 'segunda-mao': return 'Segunda Mão';
            default: return condition || 'Semi-novo';
        }
    };

    const getConditionClass = (condition) => {
        switch(condition) {
            case 'novo': return 'bg-green-50 text-green-700';
            case 'semi-novo': return 'bg-yellow-50 text-yellow-700';
            case 'segunda-mao': return 'bg-stone-300 text-stone-800';
            default: return 'bg-gray-100 text-gray-600';
        }
    };

    return (
        <div 
            onClick={onClick}
            className="bg-white rounded-xl shadow-md overflow-hidden hover:shadow-xl transition-all duration-300 transform hover:-translate-y-1 cursor-pointer"
        >
            <div className="relative h-48 bg-gray-100">
                {mainPhoto ? (
                    <img 
                        src={mainPhoto} 
                        alt={product.title} 
                        className="w-full h-full object-cover" 
                    />
                ) : (
                    <div className="w-full h-full flex items-center justify-center text-5xl">
                        {getCategoryIcon(product.category)}
                    </div>
                )}
                <span className={`absolute top-2 right-2 px-2 py-1 rounded-full text-xs font-semibold ${getConditionClass(product.condition)}`}>
                    {getConditionText(product.condition)}
                </span>
            </div>
            <div className="p-4">
                <h3 className="font-semibold text-gray-800 mb-1 line-clamp-2">{product.title}</h3>
                <p className="text-xl font-bold text-blue-600 mb-2">
                    {product.price.toLocaleString()} Kz
                </p>
                <div className="flex items-center justify-between text-sm text-gray-500">
                    <div className="flex items-center">
                        <FiMapPin className="mr-1" size={14} />
                        <span>{product.location}</span>
                    </div>
                    <span>{product.sellerName}</span>
                </div>
                <div className="text-xs text-gray-400 mt-2">
                    📞 {getContactMethodIcon(product.contactMethod)}
                </div>
            </div>
        </div>
    );
};

export default ProductCard;
